package com.jobradar.taxonomy.role; import java.time.Instant; public record RoleDto(Integer jobRoleId,String roleName,String slug,Integer categoryId,String categoryName,int opportunityCount,boolean active,Instant createdAt,Instant updatedAt){static RoleDto from(RoleEntity e){return new RoleDto(e.getId(),e.getRoleName(),e.getSlug(),e.getCategory().getId(),e.getCategory().getName(),e.getOpportunityCount(),e.isActive(),e.getCreatedAt(),e.getUpdatedAt());}}
